python3 -c "
import json
with open('/app/resources/treasury_bulletin_1982_08.json', 'r') as f:
    data = json.load(f)

# Let's explore the structure
def find_keys(d, target='Treasury bonds'):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            if target in str(k):
                results.append(k)
            results.extend(find_keys(v, target))
    elif isinstance(d, list):
        for item in d:
            results.extend(find_keys(item, target))
    return results

keys = find_keys(data, 'Treasury bonds')
print('Found keys:', keys[:20])
"
